llm_suggested_rule:
# C6: "X is called Y" - definitional sentences using 'called'
_c6_anchor = re.compile(
    r"\bis\s+called\b",
    flags=re.IGNORECASE,
)
_c6_tail = re.compile(
    r"(?:\.{1,3}|[^.])*\.",
    flags=re.DOTALL,
)

for anchor_m in _c6_anchor.finditer(inline_text):
    start_search = max(0, anchor_m.start() - 120)
    prefix = inline_text[start_search:anchor_m.start()]
    dot_pos = prefix.rfind(".")
    if dot_pos >= 0:
        name_start = start_search + dot_pos + 1
    else:
        name_start = start_search
    name_text = inline_text[name_start:anchor_m.start()].strip()
    if not name_text or len(name_text) > 120:
        continue
    tail_m = _c6_tail.match(inline_text, anchor_m.end())
    if not tail_m:
        continue
    full_text = inline_text[name_start:tail_m.end()]
    if _referential.search(full_text):
        continue
    _ns6 = name_start
    class _C6Match:
        def group(self, key):
            if key == "full":
                return full_text
            if key == "name":
                return name_text
            return None
        def start(self):
            return _ns6
    add_inline_definition(_C6Match(), "inline_is_called")

